import decimal

def invoice_total(subtotal, discount_percent):
    discount = subtotal * discount_percent / 100
    total = subtotal - discount
    if total < 0:
        total = 0
    return float(decimal.Decimal(str(total)).quantize(decimal.Decimal('0.01'), rounding=decimal.ROUND_HALF_UP))

def dedup(items):
    seen = []
    out = []
    for it in items:
        if it not in seen:
            seen.append(it)
            out.append(it)
    return out

class Inventory:
    def __init__(self): self.items={}
    def add(self,n,q): self.items[n]=self.items.get(n,0)+q
    def restock(self,n,q):
        if q < 0: return
        self.items[n]=self.items.get(n,0)+q
    def total(self): return sum(self.items.values())

class Bank:
    def __init__(self): self.bal={}
    def open(self,n,a=0): self.bal[n]=a
    def transfer(self,s,d,amt):
        if s not in self.bal or self.bal.get(s,0) < amt:
            return False
        if s == d:
            return True
        self.bal[s] -= amt
        self.bal[d] = self.bal.get(d,0) + amt
        return True

def build_url(scheme,host,path):
    if not path.startswith('/'): path='/'+path
    return scheme+'://'+host+path

import csv
rows={'x':{'k':'x'},'y':{'k':'y'}}
for fname,key in [('a.csv','v1'),('b.csv','v2'),('c.csv','v3')]:
    for r in csv.DictReader(open(fname)):
        rows[r['k']][key]=r[key]
with open('merged.csv','w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['k','v1','v2','v3'])
    w.writeheader(); w.writerows(rows.values())

