import sys
from configparser import ConfigParser
c=ConfigParser(); c['args']={}
for a in sys.argv[1:]:
    if a.startswith('--'):
        body=a[2:]
        if '=' in body:
            k,v=body.split('=',1); c['args'][k]=v
        else:
            c['args'][body]='true'
with open('parsed.ini','w') as f:
    c.write(f)
print('PARSED')
